-- Educational media portal — initial schema (Cloudflare D1)
--
-- `media` stores metadata only. The binary payload lives in R2 under
-- `object_key`. `object_key` is always generated by the Worker, never taken
-- from the uploaded filename.

CREATE TABLE IF NOT EXISTS media (
  id            TEXT PRIMARY KEY,
  title         TEXT NOT NULL,
  description   TEXT,
  subject       TEXT NOT NULL,
  object_key    TEXT NOT NULL,
  mime_type     TEXT NOT NULL,
  file_size     INTEGER NOT NULL DEFAULT 0,
  published     INTEGER NOT NULL DEFAULT 0,
  -- 'uploading' while the client is still pushing parts, 'ready' afterwards.
  status        TEXT NOT NULL DEFAULT 'ready',
  -- R2 multipart upload id, kept so abandoned uploads can be aborted.
  r2_upload_id  TEXT,
  original_name TEXT,
  created_at    TEXT NOT NULL DEFAULT (datetime('now')),
  updated_at    TEXT NOT NULL DEFAULT (datetime('now')),
  CHECK (subject IN ('Physics', 'Chemistry', 'Biology', 'Mathematics')),
  CHECK (published IN (0, 1)),
  CHECK (status IN ('uploading', 'ready'))
);

CREATE UNIQUE INDEX IF NOT EXISTS idx_media_object_key ON media (object_key);
CREATE INDEX IF NOT EXISTS idx_media_subject_published ON media (subject, published);
CREATE INDEX IF NOT EXISTS idx_media_status_created ON media (status, created_at);

-- Administrator accounts. Passwords are PBKDF2-SHA256 hashes, never plaintext.
CREATE TABLE IF NOT EXISTS admins (
  id            TEXT PRIMARY KEY,
  username      TEXT NOT NULL UNIQUE,
  password_hash TEXT NOT NULL,
  created_at    TEXT NOT NULL DEFAULT (datetime('now'))
);

-- Sessions. The cookie holds a random token; only its SHA-256 hash is stored.
CREATE TABLE IF NOT EXISTS sessions (
  token_hash TEXT PRIMARY KEY,
  admin_id   TEXT NOT NULL,
  expires_at TEXT NOT NULL,
  created_at TEXT NOT NULL DEFAULT (datetime('now'))
);

CREATE INDEX IF NOT EXISTS idx_sessions_admin ON sessions (admin_id);

-- Login throttling, keyed by client IP.
CREATE TABLE IF NOT EXISTS login_attempts (
  ip        TEXT PRIMARY KEY,
  attempts  INTEGER NOT NULL DEFAULT 0,
  window_at TEXT NOT NULL
);
